mapper.select:
SELECT a.kwlg_id, a.kwlg_tit, a.kwlg_func_tp_cd, a.kwlg_diet_tp_cd, COALESCE(a.kwlg_view_qty, 0) AS kwlg_view_qty, a.kwlg_link_url, a.kwlg_atch_url, a.kwlg_aut, a.cre_usr_id, a.cre_dt, a.upd_usr_id, a.upd_dt, count(*) over() AS ttl_no, b.intg_cd_dp_val_desc AS kwlg_func_tp_nm, c.intg_cd_dp_val_desc AS kwlg_diet_tp_nm, count(*) over() + 1 - ROW_NUMBER() over(
ORDER BY a.${orderByField} DESC
ORDER BY a.cre_dt DESC, a.kwlg_id
) as no FROM kwlg_mgmt a LEFT JOIN com_intg_cd_dtl b ON ( b.intg_cd = 'CD00008' AND a.kwlg_func_tp_cd = b.intg_cd_val_ctnt ) LEFT JOIN com_intg_cd_dtl c ON ( c.intg_cd = 'CD00011' AND a.kwlg_diet_tp_cd = c.intg_cd_val_ctnt ) WHERE 1 = 1
AND UPPER(a.kwlg_tit) LIKE #{kwlgTit}
AND a.cre_dt >= #{creDtFm}
AND a.cre_dt <= #{creDtTo}::TIMESTAMP + INTERVAL '23 hours 59 minutes 59 seconds'
AND a.kwlg_func_tp_cd = #{kwlgFuncTpCd}
AND a.kwlg_diet_tp_cd = #{kwlgDietTpCd}
ORDER BY a.${orderByField} DESC
ORDER BY a.cre_dt DESC, a.kwlg_id
OFFSET ${offset}
LIMIT ${limit}

mapper.update:
    	UPDATE kwlg_mgmt 
		SET kwlg_view_qty = (
			SELECT COALESCE(kwlg_view_qty, 0) + 1
			FROM kwlg_mgmt 
			WHERE kwlg_id = #{id}
		)
		WHERE kwlg_id = #{id}
